query:
query GetJobData {
    jobSearch(
        what: "python"
        location: {where: "São Paulo, Brazil", radius: 50, radiusUnit: MILES}
        limit: 100

        sort: RELEVANCE
        filters: [{ keyword: { field: "attributes", keys: ["CF3CP"] } }]
    ) {
        pageInfo {
            nextCursor
        }
        results {
            job {
                key
                title
                sourceEmployerName
                dateOnIndeed
                description {
                    html
                }
                location {
                    countryCode
                    admin1Code
                    city
                }
                compensation {
                    estimated {
                        currencyCode
                        baseSalary {
                            unitOfWork
                            range {
                                ... on Range { min max }
                                ... on AtLeast { min }
                                ... on AtMost { max }
                                ... on Exactly { value }
                            }
                        }
                    }
                    baseSalary {
                        unitOfWork
                        range {
                            ... on Range { min max }
                            ... on AtLeast { min }
                            ... on AtMost { max }
                            ... on Exactly { value }
                        }
                    }
                    currencyCode
                }
                attributes {
                    key
                    label
                }
                employer {
                    relativeCompanyPageUrl
                    name
                    ugcStats {
                        ratings {
                            overallRating {
                                value
                                count
                            }
                        }
                    }
                    dossier {
                        employerDetails {
                            addresses
                            industry
                            employeesLocalizedLabel
                            revenueLocalizedLabel
                            briefDescription
                        }
                        images {
                            squareLogoUrl
                        }
                        links {
                            corporateWebsite
                        }
                    }
                }
                recruit {
                    viewJobUrl
                }
            }
        }
    }
}
